/**
 * The world's feeds, generated by core (storyfeed/docs#41).
 *
 * Core's docs generator (`workbench/docs/generate.php` in storyfeed/storyfeed)
 * records every row of every world pack through real models into an in-memory
 * SQLite database, with the pack's verb wording registered as `Story::verb()`
 * definitions, and reads them back with the calls the pages teach. Per pack it
 * writes two files beside the pack, in `docs/.vitepress/theme/worlds/<pack>/`:
 *
 *   payloads.json  every row's node, read with `->log()`, keyed by row id
 *   scenes.json    each named scene read with `->live()`, recorded on its own,
 *                  and the rows a page builds by hand (a deletion, a composite)
 *
 * world.ts builds every scene, and `everything`, from payloads.json. The files
 * are committed, so the site builds from them with no PHP and no core; CI
 * regenerates them against core's main and fails on a difference.
 *
 *   node scripts/payloads.mjs           write the files (needs core, PHP and Composer's install)
 *   node scripts/payloads.mjs --check   exit 1 when a file is stale
 *
 * Core is STORYFEED_CORE, a storyfeed/storyfeed checkout with its Composer
 * dependencies installed. The drift guard runs `--check` wherever core is.
 */
import { execFileSync } from 'node:child_process'
import { existsSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join, resolve, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const docs = resolve(here, '..')
const worlds = resolve(docs, 'docs/.vitepress/theme/worlds')
const core = process.env.STORYFEED_CORE || '/Users/jasper/Dev/projects/storyfeed'
const check = process.argv.includes('--check')

const FILES = ['payloads.json', 'scenes.json']

/** A pack's committed file: `payloads.json` or `scenes.json`. */
export function worldFile(name, file) {
  return resolve(worlds, name, file)
}

/** Whether core is here to generate through. */
export const coreAvailable = () => existsSync(resolve(core, 'vendor/autoload.php'))

/** Runs core's generator on this checkout's world; returns {pack: {file: contents}}. */
export function generate() {
  const out = mkdtempSync(join(tmpdir(), 'storyfeed-docs-'))
  try {
    const world = join(out, 'world.json')
    writeFileSync(world, execFileSync(process.execPath, [resolve(core, 'workbench/docs/export-world.mjs'), docs], {
      encoding: 'utf8',
      maxBuffer: 64 * 1024 * 1024,
    }))
    execFileSync(process.env.PHP_BINARY || 'php', [resolve(core, 'workbench/docs/generate.php'), `--world=${world}`, `--out=${out}`], {
      env: { ...process.env, NODE_BINARY: process.execPath },
      stdio: ['ignore', 'ignore', 'inherit'],
    })

    return Object.fromEntries(readdirSync(out, { withFileTypes: true }).filter((entry) => entry.isDirectory())
      .map(({ name }) => [name, Object.fromEntries(FILES.map((file) => [file, readFileSync(join(out, name, file), 'utf8')]))]))
  } finally {
    rmSync(out, { recursive: true, force: true })
  }
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  if (!coreAvailable()) {
    console.log(`payloads: core not at ${core} — skipped (set STORYFEED_CORE to run it here)`)
    process.exit(check ? 0 : 1)
  }

  let stale = 0
  for (const [name, files] of Object.entries(generate())) {
    for (const [file, fresh] of Object.entries(files)) {
      const path = worldFile(name, file)
      if (check) {
        if (!existsSync(path) || readFileSync(path, 'utf8') !== fresh) {
          console.error(`payloads: ${name}/${file} does not match core. Run \`npm run payloads\`.`)
          stale++
        }
      } else {
        writeFileSync(path, fresh)
        console.log(`payloads: wrote ${name}/${file}`)
      }
    }
  }

  if (check && stale === 0) console.log('payloads: every world matches core')
  process.exit(stale ? 1 : 0)
}
